// src/Central/FindingText.php, row 336
"The text prints data of the request, of a user or of the server: {server} server variables, {cookie} the cookies of the visitor, {userinfo} the login log of any user, {user:password} the password the user signed in with." => "Tekst ispisuje podatke zahtjeva, korisnika ili servera: {server} varijable servera, {cookie} kolačiće posjetitelja, {userinfo} zapisnik prijava bilo kojeg korisnika, {user:password} lozinku kojom se korisnik prijavio.", // ai 2026-10

// src/Central/FindingText.php, row 337
