// src/Central/FindingText.php, row 358
"Fine over the texts of the app itself; do not install it when it expands item content filled by anonymous posting or parameters of the URL." => "U redu nad tekstovima same aplikacije; nemojte je instalirati ako razvija sadržaj stavki ispunjen anonimnim slanjem ili parametrima URL-a.", // ai 2026-10

